#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    expect: Expect,
}

/// What the tokenizer looks for at `pos`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Expect {
    /// A timestamp, a key or a word, possibly after blanks.
    Token,
    /// The value right after a key's `=`.
    Value,
    /// Nothing: the line is used up or an error has been reported.
    Done,
}

/// A token that was read, where reading stopped, and what has to come next.
struct Lexed<'a> {
    token: Token<'a>,
    end: usize,
    then: Expect,
}

type LexResult<'a> = Result<Lexed<'a>, LexError>;

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, expect: Expect::Token }
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let lexed = match self.expect {
            Expect::Done => return None,
            Expect::Value => lex_value(self.src, self.pos),
            Expect::Token => {
                self.pos = skip_blanks(self.src.as_bytes(), self.pos);
                if self.pos == self.src.len() {
                    self.expect = Expect::Done;
                    return None;
                }
                lex_token(self.src, self.pos)
            }
        };
        Some(match lexed {
            Ok(Lexed { token, end, then }) => {
                self.pos = end;
                self.expect = then;
                Ok(token)
            }
            Err(error) => {
                self.pos = self.src.len();
                self.expect = Expect::Done;
                Err(error)
            }
        })
    }
}

/// Spaces and tabs separate tokens.
#[inline]
fn is_blank(byte: u8) -> bool {
    byte == b' ' || byte == b'\t'
}

#[inline]
fn skip_blanks(bytes: &[u8], from: usize) -> usize {
    let mut pos = from;
    while pos < bytes.len() && is_blank(bytes[pos]) {
        pos += 1;
    }
    pos
}

/// The first position at or after `from` whose byte satisfies `stop`, or the end of the line.
#[inline]
fn scan_until(bytes: &[u8], from: usize, stop: impl Fn(u8) -> bool) -> usize {
    let mut pos = from;
    while pos < bytes.len() && !stop(bytes[pos]) {
        pos += 1;
    }
    pos
}

/// A closing `]` or `"` must be followed by a blank or the end of the line.
#[inline]
fn expect_separator(bytes: &[u8], pos: usize) -> Result<(), LexError> {
    match bytes.get(pos) {
        Some(&byte) if !is_blank(byte) => Err(LexError::ExpectedSeparator { pos }),
        _ => Ok(()),
    }
}

/// Reads a timestamp, key or word starting at the non-blank byte at `start`.
#[inline]
fn lex_token(src: &str, start: usize) -> LexResult<'_> {
    match src.as_bytes()[start] {
        b'[' => lex_timestamp(src, start),
        b'"' => Err(LexError::UnexpectedQuote { pos: start }),
        b'=' => Err(LexError::EmptyKey { pos: start }),
        _ => lex_key_or_word(src, start),
    }
}

/// `[text]`, with `open` at the `[`.
#[inline]
fn lex_timestamp(src: &str, open: usize) -> LexResult<'_> {
    let bytes = src.as_bytes();
    let body = open + 1;
    let close = scan_until(bytes, body, |byte| byte == b']' || byte == b'[');
    match bytes.get(close) {
        None => Err(LexError::UnterminatedTimestamp { pos: open }),
        Some(b'[') => Err(LexError::NestedBracket { pos: close }),
        Some(_) => {
            expect_separator(bytes, close + 1)?;
            Ok(Lexed { token: Token::Timestamp(&src[body..close]), end: close + 1, then: Expect::Token })
        }
    }
}

/// `key=` (the value follows separately) or a plain word.
#[inline]
fn lex_key_or_word(src: &str, start: usize) -> LexResult<'_> {
    let bytes = src.as_bytes();
    let end = scan_until(bytes, start, |byte| is_blank(byte) || byte == b'=' || byte == b'"');
    match bytes.get(end) {
        Some(b'"') => Err(LexError::UnexpectedQuote { pos: end }),
        Some(b'=') => Ok(Lexed { token: Token::Key(&src[start..end]), end: end + 1, then: Expect::Value }),
        _ => Ok(Lexed { token: Token::Word(&src[start..end]), end, then: Expect::Token }),
